x=np.array([8,14]);exercise=np.maximum(x-9,0);cont=np.array([.8730,5.4286]);w=.32;ax.bar(x-w/2,exercise,w,color=MUTED,label='exercise now');ax.bar(x+w/2,cont,w,color=ACCENT,label='wait');ax.set_xticks(x,['down node X=$8M','up node X=$14M'],rotation=12);ax.set_ylabel('Value (USD M)');ax.set_title('Dynamic policy at year 1',loc='left');ax.legend(fontsize=7.5);ax.grid(axis='y',alpha=.2)
